sys_script_include.script:
var CourseUtils = Class.create();
CourseUtils.prototype = {
    initialize: function() {},

    refQualCourseSchedule: function(currentCourseId) {
        var studentId = gs.getUserID();
        var excludedScheduleIds = [];
        var excludedCourseIds = [];

        // --- STORY 7 ---
        var grUserEnroll = new GlideRecord("x_875435_course_0_enrollment");
        grUserEnroll.addEncodedQuery("stateIN2,3^student=" + studentId);
        grUserEnroll.query();
        while (grUserEnroll.next()) {
            excludedScheduleIds.push(grUserEnroll.getValue('course_schedule'));
        }

        // --- STORY 8 ---
        var aggCourse = new GlideAggregate("x_875435_course_0_enrollment");
        aggCourse.addEncodedQuery("stateIN2,3^course!=NULL^student=" + studentId);
        aggCourse.addAggregate('COUNT');
        aggCourse.groupBy('course');
        aggCourse.query();
        while (aggCourse.next()) {
            var approvedCount = parseInt(aggCourse.getAggregate('COUNT'), 10);
            if (approvedCount >= 3) {
                excludedCourseIds.push(aggCourse.getValue('course'));
            }
        }

        // --- STORY 9 ---
        var scheduleCounts = {};
        var aggSched = new GlideAggregate("x_875435_course_0_enrollment");
        aggSched.addEncodedQuery("stateIN2,3^course_schedule!=NULL");
        aggSched.addAggregate('COUNT');
        aggSched.groupBy('course_schedule');
        aggSched.query();
        while (aggSched.next()) {
            var schedId = aggSched.getValue('course_schedule');
            scheduleCounts[schedId] = parseInt(aggSched.getAggregate('COUNT'), 10);
        }
        var grCapacityCheck = new GlideRecord("x_875435_course_0_course_schedule");
        grCapacityCheck.addActiveQuery();
        grCapacityCheck.query();
        while (grCapacityCheck.next()) {
            var currentSchedId = grCapacityCheck.getUniqueValue();
            var currentCapacity = parseInt(grCapacityCheck.getValue('capacity'), 10) || 0;
            var currentEnrollments = scheduleCounts[currentSchedId] || 0;

            if (currentEnrollments >= currentCapacity) {
                excludedScheduleIds.push(currentSchedId);
            }
        }

		// --- STORY 10, 11 ---
        var query = "training_date>javascript:gs.endOfToday()^instructor!=" + studentId;
        if (currentCourseId) {
            query += "^course=" + currentCourseId;
        }
        if (excludedScheduleIds.length > 0) {
            query += "^sys_idNOT IN" + excludedScheduleIds.join(',');
        }
        if (excludedCourseIds.length > 0) {
            query += "^courseNOT IN" + excludedCourseIds.join(',');
        }

        return query;
    },
    type: 'CourseUtils'
};
